function countSteepPairs(nums: number[]): number {
  const a = nums.slice(), tmp = new Array(a.length);
  const sort = (lo: number, hi: number): number => { // sorts a[lo, hi)
    if (hi - lo < 2) return 0;
    const mid = (lo + hi) >> 1;
    let count = sort(lo, mid) + sort(mid, hi);
    let p = mid;
    for (let i = lo; i < mid; i++) {
      while (p < hi && a[i] > 2 * a[p]) p++;
      count += p - mid;
    }
    let i = lo, j = mid, k = lo;
    while (i < mid || j < hi) tmp[k++] = j >= hi || (i < mid && a[i] <= a[j]) ? a[i++] : a[j++];
    for (let x = lo; x < hi; x++) a[x] = tmp[x];
    return count;
  };
  return sort(0, a.length);
}

