function countSteepPairs(nums: number[]): number {
  const sorted = [...new Set(nums)].sort((x, y) => x - y);
  const m = sorted.length, tree = new Array(m + 1).fill(0);
  // number of sorted values strictly less than v
  const below = (v: number): number => {
    let lo = 0, hi = m;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (sorted[mid] < v) lo = mid + 1; else hi = mid; }
    return lo;
  };
  let count = 0;
  for (let i = nums.length - 1; i >= 0; i--) {
    // seen values y with nums[i] > 2y, i.e. 2y < nums[i]
    let k = below(nums[i] / 2);
    for (; k > 0; k -= k & -k) count += tree[k];
    for (let j = below(nums[i]) + 1; j <= m; j += j & -j) tree[j]++;
  }
  return count;
}

